public bool IsExpensive(decimal price) => price > 1000m;

// Throws at runtime: cannot translate 'IsExpensive'
var expensiveProducts = await dbContext.Products
    .Where(p => IsExpensive(p.Price))
    .ToListAsync();

// Works — EF Core translates the comparison directly
var expensiveProducts = await dbContext.Products
    .Where(p => p.Price > 1000m)
    .ToListAsync();

// EF.Functions.Like translates to SQL LIKE
var discounted = await dbContext.Products
    .Where(p => EF.Functions.Like(p.Name, "%sale%"))
    .ToListAsync();

// Raw SQL for complex patterns
var recent = await dbContext.Products
    .Where(p => EF.Functions.DateDiffDay(p.CreatedAt, DateTime.UtcNow) < 7)
    .ToListAsync();
